function legacyLeavesPage(){const leaves=state.leaves.filter(l=>(isHR()||l.employeeId===employeeId||role==='manager'&&person(l.employeeId)?.manager===employeeId)&&(!department||person(l.employeeId)?.department===department)&&l.from<=to&&l.to>=from),e=person(employeeId);return heading('إجازة منظمة. فريق متوازن.','طلب واضح، رصيد معروف، وموافقات متتابعة.',btn('＋ طلب إجازة','leaveForm','','primary'),'TIME OFF & APPROVALS')+filters()+'<div class="kpis">'+kpi('طلبات خلال الفترة',leaves.length,'حسب تواريخ الإجازة','☷')+kpi('بانتظار القرار',leaves.filter(l=>l.status==='pending').length,'المدير ثم الموارد البشرية','◷')+kpi('طلبات معتمدة',leaves.filter(l=>l.status==='approved').length,'الاعتماد النهائي فقط','✓')+kpi('رصيد الموظف التجريبي',e?e.leaveBalance-e.usedLeave:'—',e?esc(e.name)+' • أيام سنوية متبقية':'','◇',true)+'</div>'+card('مركز الطلبات','يُخصم الرصيد السنوي بعد الموافقة النهائية فقط',table(['الموظف','نوع الإجازة','الفترة','أيام العمل','مسار الموافقة','القرار'],leaves.map(l=>'<tr><td>'+avatar(person(l.employeeId))+'</td><td>'+esc(l.type)+'</td><td class="mono">'+l.from+' → '+l.to+'</td><td>'+l.days+'</td><td>'+badge(l.status)+'<div class="approval-chain"><span class="'+(l.stage>=1?'done':'')+'">1. المدير</span>←<span class="'+(l.stage>=2?'done':'')+'">2. HR</span></div></td><td>'+btn('تفاصيل وموافقة','leave',l.id,'small')+'</td></tr>')));}
function legacyPayrollPage(){const run=state.payroll.find(r=>r.month===month),total=run?.rows.reduce((a,r)=>a+r.net,0)||0;return heading('رواتب واضحة. كل شهر.','جهّز، راجع، اعتمد، ثم أرسل كشفًا منفصلًا لكل موظف.', '<input id="payMonth" type="month" aria-label="شهر الرواتب" value="'+month+'">'+btn('تجهيز الشهر','preparePayroll','','primary'),'PAYROLL WORKSPACE')+'<div class="notice">الأرقام توضيحية. الخصومات مبلغ تجريبي مُدخل؛ لا يتم حساب الضرائب أو التأمينات المصرية تلقائيًا.</div><div class="kpis">'+kpi('عدد كشوف الراتب',run?run.rows.length:0,'كشف منفصل لكل موظف','▣',true)+kpi('صافي الرواتب',fmt(total),state.settings.currency+' للشهر المختار','↗')+kpi('حالة الاعتماد',run?({draft:'مسودة',approved:'معتمد',sent:'مُرسل',simulated:'محاكاة'})[run.status]||'معالجة':'لم يجهز',run?.approvedBy?esc(run.approvedBy):'تحتاج اعتماد المالية','✓')+kpi('الإرسال الشهري',state.settings.autoSend?'مفعّل':'متوقف','يوم '+state.settings.payday+' • Africa/Cairo','◷')+'</div><div class="toolbar" style="margin-bottom:20px">'+(run?btn('اعتماد المالية','approvePayroll',run.id,'gold')+btn(LIVE?'إرسال الكشوف المعتمدة':'محاكاة إرسال الكشوف','sendPayroll',run.id,'primary'):'')+'</div>'+card('تفاصيل كشف '+month,'الراتب الأساسي + البدلات + المكافآت − الخصومات',run?table(['الموظف','الأساسي','البدلات','المكافآت','الخصومات','الصافي','التسليم',''],run.rows.map(raw=>{const r={...raw,...hrPayParts(raw)};return '<tr><td>'+avatar({name:r.name,email:r.email})+'</td><td class="mono">'+fmt(r.basic)+'</td><td class="mono">'+fmt(r.allowance)+'</td><td class="mono">'+fmt(r.bonus)+'</td><td class="mono">'+fmt(r.deduction)+'</td><td class="pay-value">'+fmt(r.net)+'</td><td><span class="badge '+(['sent','simulated'].includes(r.status)?'green':'amber')+'">'+esc(({queued:'في الانتظار',sent:'تم الإرسال',simulated:'محاكاة',error:'خطأ إرسال',sending:'قيد الإرسال'})[r.status]||r.status)+'</span></td><td>'+btn('كشف الراتب','payslip',r.employeeId,'small')+(run.status==='draft'?btn('تعديل البند','payrollRow',r.employeeId,'small'):'')+'</td></tr>';})):'<div class="empty">ابدأ بتجهيز الشهر، ثم راجع الكشف واعتمده من دور المالية.</div>')+'<div class="insight">'+(LIVE?'الإرسال الفعلي يعمل من هذه النسخة على Google Workspace بعد تفعيل الجدولة واعتماد الكشف.':'محاكاة العرض لا ترسل رسائل. نسخة Google Workspace تُنشئ PDF وتحفظه في Drive وترسله عبر البريد بعد الاعتماد.')+'</div>';}
function legacyAttendancePage(){const ids=new Set(scopedEmployees().map(e=>e.id)),a=state.attendance.filter(a=>a.date>=from&&a.date<=to&&ids.has(a.employeeId)),rows=scopedEmployees().map(e=>{const records=a.filter(r=>r.employeeId===e.id);return '<tr><td>'+avatar(e)+'</td><td>'+records.length+'</td><td>'+records.filter(r=>r.status==='present').length+'</td><td>'+records.filter(r=>r.status==='late').length+'</td><td>'+records.filter(r=>r.status==='absent').length+'</td><td>'+(records.length?fmt(records.filter(r=>r.status!=='absent').length/records.length*100)+'%':'—')+'</td></tr>';});return heading('افهم الحضور، قبل القرار.','تجميع سجلات الحضور داخل الفترة المختارة. الجمعة والسبت عطلة في بيانات العرض.','','ATTENDANCE INSIGHTS')+filters(true)+'<div class="notice blue">سجلات العرض تجريبية حتى 14 أكتوبر 2026. لا يوجد جهاز بصمة أو تتبع موقع متصل بهذه النسخة.</div>'+card('ملخص الحضور حسب الموظف',fmt(a.length)+' سجل في الفترة',table(['الموظف','السجلات','في الموعد','متأخر','غائب','معدل الحضور'],rows));}
function performancePage(){return heading('النمو يحتاج محادثة جيدة.','مراجعات بشرية وخطط تطوير واضحة؛ التقييم لا يقرر التعيين أو الفصل تلقائيًا.',(role==='employee'?'':btn('＋ مراجعة أداء','reviewForm','','primary')),'PERFORMANCE & GROWTH')+card('المراجعات المسجلة','تقييم من 1 إلى 5 مع ملاحظة عملية',table(['الموظف','تاريخ المراجعة','التقييم','الملاحظات'],state.reviews.filter(r=>r.date>=from&&r.date<=to).map(r=>'<tr><td>'+avatar(person(r.employeeId))+'</td><td>'+r.date+'</td><td><span class="rating">'+('★'.repeat(Math.round(r.score)))+'</span> '+r.score+'/5</td><td>'+esc(r.notes)+'</td></tr>')))+ '<div style="margin-top:20px">'+filters()+'</div>';}
const exitTasks=['تسليم المهام والملفات','استرداد الأجهزة والعهد','تسوية المستحقات ومراجعة المالية','تأكيد إغلاق الوصول بواسطة مسؤول IT'];
function offboardingPage(){return heading('نهاية مهنية، بتفاصيل مكتملة.','قرار بشري موثق، ثم تسليم وإخلاء طرف وتسوية.',btn('＋ حالة إنهاء خدمة','offboardingForm','','primary'),'OFFBOARDING WITH CARE')+'<div class="notice blue">قائمة إغلاق الوصول توثّق تأكيد مسؤول IT؛ لا تُعطل أي حساب خارجي تلقائيًا.</div><div class="grid equal">'+state.offboarding.map(o=>card(esc(person(o.employeeId)?.name||o.employeeId),esc(o.reason)+' • آخر يوم '+o.lastDay,'<div class="toolbar">'+badge(o.status)+'</div>'+exitTasks.map((t,i)=>'<label class="checklist"><input type="checkbox" data-action="exitTask" data-id="'+o.id+'" data-index="'+i+'" '+(o.tasks[i]?'checked':'')+' '+(o.status==='completed'?'disabled':'')+'>'+t+'</label>').join('')+'<div class="form-actions">'+btn('إغلاق الحالة','finalizeExit',o.id,'danger')+'</div>')).join('')+'</div>';}
function calendarPage(){const [y,m]=month.split('-').map(Number),days=new Date(y,m,0).getDate(),offset=(new Date(y,m-1,1).getDay()+1)%7;return heading('المواعيد التي تحرك الفريق.','إجازات معتمدة، رواتب ومواعيد إدارة الأفراد.','<input id="payMonth" type="month" aria-label="شهر التقويم" value="'+month+'">'+(isHR()?btn('＋ إضافة موعد','eventForm','','primary'):''),'TEAM CALENDAR')+card('تقويم '+month,'يمكن تغيير الشهر أو إضافة موعد جديد','<div class="calendar-grid">'+['السبت','الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة'].map(d=>'<div class="calendar-weekday">'+d+'</div>').join('')+Array.from({length:offset},()=>'<div></div>').join('')+Array.from({length:days},(_,i)=>{const d=month+'-'+String(i+1).padStart(2,'0');return '<div class="calendar-cell">'+(i+1)+state.events.filter(e=>e.date===d).map(e=>'<span class="badge">'+esc(e.title)+'</span>').join('')+state.leaves.filter(l=>l.status==='approved'&&l.from<=d&&l.to>=d).map(l=>'<span class="badge green">إجازة '+esc(person(l.employeeId)?.name.split(' ')[0])+'</span>').join('')+'</div>';}).join('')+'</div>');}
function settingsPage(){return heading('اجعله يعكس شركتك.','غيّر الهوية، اضبط موعد الرواتب، وجهّز ربط Google Workspace.','','YOUR WORKSPACE, YOUR WAY')+'<div class="settings-grid">'+card('الهوية وإعدادات الرواتب','الشعار والاسم واللون قابلون للتغيير','<form id="settingsForm">'+field('اسم الشركة','company','text',state.settings.company)+field('اسم المنتج','product','text',state.settings.product)+field('اللون الأساسي المميز','accent','color',state.settings.accent)+'<div class="field"><label for="logoUpload">شعار الشركة · PNG / SVG / JPEG (أقل من 500 KB)</label><input type="file" id="logoUpload" accept="image/png,image/jpeg,image/svg+xml"><small>يُحفظ ضمن إعدادات العرض</small></div>'+field('يوم إرسال كشوف الرواتب (1–28)','payday','number',state.settings.payday,'min="1" max="28"')+'<label class="checklist"><input type="checkbox" name="autoSend" '+(state.settings.autoSend?'checked':'')+' '+''+'>تفعيل الجدولة '+(LIVE?'(تشغيل حقيقي)' :'التجريبية')+'</label><div class="form-actions"><button class="btn primary" type="submit">حفظ الإعدادات</button></div></form>')+card('Google Workspace','Google Sheets + Drive + Apps Script','<div class="google-mini" style="color:var(--text);border:0;padding:0 0 18px"><span class="google-logo">G</span><div><b>'+(LIVE?'متصل عبر Apps Script':'جاهز للإعداد • غير متصل حاليًا')+'</b><small>'+(LIVE?'الهوية والصلاحيات تُتحقق على الخادم':'بيانات العرض محفوظة في هذا المتصفح فقط')+'</small></div></div><div class="action-row"><span class="action-icon">▦</span><div><b>Google Sheets</b><small>الموظفون، المرشحون، الإجازات والاعتمادات</small></div></div><div class="action-row"><span class="action-icon">▱</span><div><b>Google Drive</b><small>نسخ مؤرخة وكشوف راتب PDF خاصة</small></div></div><div class="action-row"><span class="action-icon">↗</span><div><b>Apps Script + Gmail</b><small>صلاحيات حسب الدور، قفل كتابة، وإرسال شهري بعد اعتماد المالية</small></div></div><div class="form-actions"><a class="btn primary" href="Zarqa-People-Google-Workspace.zip" download>تحميل نسخة Google Workspace</a>'+btn('خطوات الربط','integration','','small')+'<a class="btn" href="Zarqa-People-Open-Source.zip" download>تحميل الكود المفتوح</a>'+'</div><p style="font-size:10px;margin-top:15px">النسخة المستضافة هنا '+(LIVE?'تستخدم Google Workspace.':'تعمل محليًا في المتصفح. شغّل الحزمة على Apps Script لتفعيل الاتصال الحقيقي.')+'</p>')+'</div><div style="margin-top:20px" class="settings-grid">'+card('إدارة البيانات','نسخة احتياطية قابلة للنقل','<div class="toolbar">'+btn('تصدير بيانات JSON','exportData')+(LIVE?'':btn('استيراد نسخة','importData')+btn('استعادة بيانات العرض','resetDemo','','danger'))+'</div><p style="font-size:10px;margin-top:15px">'+(LIVE?'التصدير متاح لمسؤول النظام حسب الصلاحية.':'اختيار الدور هنا لأغراض الشرح. هذه نسخة تجريبية، وليست نظام دخول موظفين فعليًا.')+'</p>')+card('سجل الإجراءات','أحدث تغييرات مساحة العمل',state.audit.slice(0,8).map(a=>'<div class="audit-row"><span>'+esc(a.action)+'<small style="display:block">'+esc(a.actor)+'</small></span><small class="mono">'+a.at.slice(0,16).replace('T',' ')+'</small></div>').join(''))+'</div>';}
function render(){hrEnsureOperations(state);document.body.classList.toggle('portal-mode',page==='portal');document.body.classList.toggle('employee-session',employeeSession);if(!allowedPages().includes(page))page=allowedPages()[0];renderBrand();renderNav();renderUiChrome();$('main').innerHTML=({dashboard,requests:requestsPage,scheduler:schedulerPage,documents:archivePage,reports:reportsPage,orgchart:orgchartPage,employees:employeesPage,recruitment:recruitmentPage,onboarding:onboardingPage,leaves:leavesPage,payroll:payrollPage,attendance:attendancePage,performance:performancePage,offboarding:offboardingPage,calendar:calendarPage,settings:settingsPage,data:dataCenterPage,laws:lawsPage,selfservice:selfServicePage,portal:portalPage})[page]();if(page==='onboarding'){const docId=isHR()?employeeFocus:employeeId;if(person(docId))$('main').innerHTML+=documentSection(docId);}if(page==='selfservice')$('main').innerHTML+=documentSection(employeeId);if(page==='settings'&&role==='admin')$('main').innerHTML+=dataCenterShortcut();if(!isHR())document.querySelectorAll('[data-action="employeeForm"]').forEach(x=>x.remove());if(!LIVE)localStorage.setItem('zarqa-people-v1',JSON.stringify(state));applyLanguage();}
function navigate(id){page=id;location.hash=id;render();setSidebar(false);$('accountMenu').open=false;window.scrollTo(0,0);}
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');setTimeout(()=>$('toast').classList.remove('visible'),4500);}
function modal(html){$('dialogBody').innerHTML=html;if(!$('dialog').open)$('dialog').showModal();}
function closeModal(){$('dialog').close();}
function form(title,body,type){modal('<h2>'+title+'</h2><form data-form="'+type+'">'+body+'<div class="form-actions"><button class="btn primary" type="submit">حفظ ومتابعة</button><button class="btn" type="button" data-action="close">إلغاء</button></div></form>');}
async function mutate(action,payload,message='تم الحفظ'){if(busy)return;busy=true;try{if(LIVE){state=await callServer('mutate',{action,payload});}else hrMutate(state,action,payload,{role,email:role+'@example.com',employeeId,demo:true});closeModal();render();toast(message);}catch(e){toast(e.message||String(e));}finally{busy=false;}}
function callServer(action,payload={}){return new Promise((resolve,reject)=>google.script.run.withSuccessHandler(resolve).withFailureHandler(reject).api(action,payload));}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows){return '\ufeff'+rows.map(r=>r.map(c=>'"'+String(c??'').replace(/"/g,'""').replace(/^[=+\-@]/,"'$&")+'"').join(',')).join('\r\n');}
function recommendations(){const m=hrMetrics(state,from,to,department);modal('<span class="eyebrow">FOCUS, THEN ACT</span><h2>ثلاث أولويات للفترة المحددة</h2><p>توصيات بقواعد واضحة من البيانات؛ لا تحتاج نموذج AI.</p>'+[{title:'1. قلّل انتظار الموافقات',body:m.pending+' طلبات معلقة. راجع طلبات المدير أولًا ثم طلبات HR.',nav:'leaves'},{title:'2. أكمل رحلة المنضمين',body:m.onboarding+' موظفين لم يكملوا السياسات. خصص جلسة ترحيب ومتابعة.',nav:'onboarding'},{title:'3. اقفل الرواتب قبل موعد الإرسال',body:'جهّز '+month+' ثم اعتمده من المالية. الإرسال مرتبط بالكشف المعتمد فقط.',nav:'payroll'}].map(r=>'<div class="module"><div><h3>'+r.title+'</h3><p>'+r.body+'</p></div>'+btn('افتح','recommendNav',r.nav,'small')+'</div>').join(''));}
function profile(id){const e=person(id);modal('<div class="person"><span class="avatar large">'+initials(e.name)+'</span><div><h2>'+esc(e.name)+'</h2><p>'+esc(e.job)+' • '+esc(e.department)+'</p>'+badge(e.status)+'</div></div><div class="form-grid" style="margin-top:25px"><div class="field"><label>البريد</label><b class="mono">'+esc(e.email)+'</b></div><div class="field"><label>رقم الموظف</label><b>'+e.id+'</b></div><div class="field"><label>تاريخ الانضمام</label><b>'+e.joinDate+'</b></div><div class="field"><label>رصيد الإجازة</label><b>'+(e.leaveBalance-e.usedLeave)+' يوم</b></div>'+(isHR()||isFin()?'<div class="field"><label>الراتب الأساسي</label><b>'+money(e.salary)+'</b></div>':'')+'<div class="field"><label>السياسات</label><b>'+e.onboarding.length+'/'+state.policies.length+'</b></div></div><div class="form-actions">'+(isHR()?btn('رحلة الانضمام','onboardProfile',e.id,'primary')+btn('تعديل بيانات الموظف','editEmployee',e.id):'')+'</div>');}
function employeeForm(){form('إضافة موظف', '<div class="form-grid">'+field('الاسم','name')+field('البريد الإلكتروني','email','email')+field('المسمى الوظيفي','job')+selectField('القسم','department',[...new Set(state.employees.map(e=>e.department))])+field('الراتب الأساسي','salary','number','18000','min="0"')+field('تاريخ الانضمام','joinDate','date',new Date().toISOString().slice(0,10))+'</div>','employee');}
function jobForm(){form('وظيفة جديدة','<div class="form-grid">'+field('المسمى','title')+selectField('القسم','department',[...new Set(state.employees.map(e=>e.department))])+field('الموقع وطريقة العمل','location','text','القاهرة · هجين')+field('نطاق الراتب','salary','text','18,000–25,000 EGP')+'</div><div class="field"><label for="f-description">وصف الوظيفة ومتطلباتها</label><textarea id="f-description" name="description" required></textarea></div>','job');}
