function leaveForm(){form('طلب إجازة','<div class="form-grid">'+selectField('الموظف','employeeId',isHR()?employeeOptions(true):employeeOptions().filter(o=>o.value===employeeId))+selectField('نوع الإجازة','type',['سنوية','مرضية','بدون أجر'])+field('من','from','date','2026-10-18')+field('إلى','to','date','2026-10-20')+'</div><div class="field"><label for="leave-reason">السبب</label><textarea id="leave-reason" name="reason" required></textarea></div><p>أيام العمل تستبعد الجمعة والسبت. الطلب لا يعتمد نفسه ولا يخصم الرصيد قبل الموافقة النهائية.</p>','leave');}
function leave(id){requestDetail('leave|'+id);}
function moduleModal(id){const e=person(isHR()?employeeFocus:employeeId),m=state.policies.find(m=>m.id===Number(id));modal('<span class="eyebrow">CHAPTER 0'+(m.id+1)+'</span><h2>'+esc(m.title)+'</h2><div class="notice blue">'+esc(m.text)+'</div><h3>'+esc(m.question)+'</h3><form data-form="module"><input type="hidden" name="employeeId" value="'+e.id+'"><input type="hidden" name="moduleId" value="'+m.id+'"><div class="question-options">'+m.options.map((o,i)=>'<label><input type="radio" name="answer" value="'+i+'" required>'+esc(o)+'</label>').join('')+'</div><label class="checklist"><input type="checkbox" name="ack" required>قرأت وفهمت السياسة بإصدار '+esc(state.settings.policyVersion)+'</label><div class="form-actions"><button type="submit" class="btn primary">تأكيد واجتياز المحطة</button></div></form>');}
function payslip(id){const run=state.payroll.find(r=>r.month===month),raw=run?.rows.find(r=>r.employeeId===id),r=raw?{...raw,...hrPayParts(raw)}:null;if(!r)return;modal('<span class="eyebrow">'+esc(state.settings.product)+'</span><h2>كشف راتب '+month+'</h2><p>'+esc(state.settings.company)+' • '+esc(r.name)+'</p><p class="mono">'+esc(r.employeeId)+' · '+esc(r.email)+'</p><div class="statline">الحالة '+badge(run.status)+'</div>'+table(['البند','المبلغ'],[['الراتب الأساسي',r.basic],['البدلات',r.allowance],['المكافآت',r.bonus],['الخصومات',r.deduction]].map(v=>'<tr><td>'+v[0]+'</td><td class="mono">'+money(v[1])+'</td></tr>'))+'<div class="hero-panel" style="margin-top:20px;padding:20px"><div><p>صافي المستحق</p><h2 class="mono">'+money(r.net)+'</h2></div></div><p>كشف '+(LIVE?'إلكتروني':'تجريبي')+'، وليس إثبات تحويل بنكي.</p><div class="form-actions no-print">'+btn('طباعة / حفظ PDF','print','','primary')+'</div>');}
function integration(){cloudSetup();}
function help(){modal('<span class="eyebrow">RECORD A GREAT DEMO</span><h2>رحلة فيديو في 7 خطوات</h2><ol style="line-height:2.2;padding-right:20px"><li>ابدأ بالداشبورد وغيّر الفترة بين سبتمبر وأكتوبر.</li><li>أضف وظيفة ثم مرشحًا وحرّكه إلى عرض العمل.</li><li>اعتمده كموظف، وافتح رحلة الانضمام.</li><li>حل موقف سياسة ثم أكد القراءة؛ ستزيد نسبة الإنجاز.</li><li>من دور الموظف قدّم إجازة، ثم بدّل للمدير وHR للموافقتين.</li><li>جهّز الرواتب، بدّل للمالية، اعتمد ثم شغّل محاكاة الإرسال.</li><li>اعرض إخلاء الطرف ثم غيّر اسم الشركة والشعار من الإعدادات.</li></ol><p>البيانات التجريبية محفوظة في نفس المتصفح. زر استعادة بيانات العرض يبدأ الشرح من جديد.</p>');}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-nav],[data-action]');if(!el)return;if(el.dataset.nav){navigate(el.dataset.nav);return;}const id=el.dataset.id,a=el.dataset.action;try{switch(a){case 'nav':navigate(id);break;case 'recommendNav':closeModal();navigate(id);break;case 'close':closeModal();break;case 'recommendations':recommendations();break;case 'profile':profile(id);break;case 'editEmployee':employeeEditForm(id);break;case 'accessForm':if(role==='admin')accessForm();break;case 'payrollRow':payrollRowForm(id);break;case 'employeeForm':employeeForm();break;case 'jobForm':jobForm();break;case 'candidateForm':candidateForm(id);break;case 'candidate':candidate(id);break;case 'recruitTab':recruitTab=id;render();break;case 'publishJob':await mutate('job.publish',{id},'تم تحديث حالة الإعلان الداخلي');break;case 'job':{const j=job(id);modal('<h2>'+esc(j.title)+'</h2><p>'+esc(j.location)+' • '+esc(j.salary)+'</p><div class="module">'+esc(j.description)+'</div>'+btn('نسخ الإعلان','copyJob',id,'primary'));break;}case 'copyJob':{const j=job(id);await navigator.clipboard.writeText(j.title+'\n'+j.location+'\n'+j.salary+'\n'+j.description);toast('تم نسخ الإعلان؛ انشره على قناتك المختارة');break;}case 'onboardProfile':employeeFocus=id;closeModal();navigate('onboarding');break;case 'module':moduleModal(id);break;case 'policies':modal('<h2>السياسات ومواقف الفهم</h2>'+state.policies.map(m=>'<div class="module"><div><h3>'+esc(m.title)+'</h3><p>إصدار '+state.settings.policyVersion+'</p></div>'+btn('تعديل','editPolicy',m.id,'small')+'</div>').join(''));break;case 'editPolicy':{const m=state.policies.find(m=>m.id===Number(id));form('تعديل '+esc(m.title),'<input type="hidden" name="id" value="'+id+'"><div class="field"><label>نص السياسة</label><textarea name="text" required>'+esc(m.text)+'</textarea></div>'+field('الموقف / السؤال','question','text',m.question)+m.options.map((o,i)=>field('الخيار '+(i+1),'option'+i,'text',o)).join('')+selectField('الإجابة الصحيحة','correct',m.options.map((o,i)=>({value:String(i),label:o})),String(m.correct))+'<p>تعديل السياسة يرفع الإصدار ويلزم الموظفين بإعادة اجتياز هذه المحطة.</p>','policy');break;}case 'leaveForm':leaveForm();break;case 'leave':leave(id);break;case 'approveLeave':await mutate('leave.decide',{id,decision:'approved'},'تم تسجيل الموافقة في المسار');break;case 'rejectLeave':await mutate('leave.decide',{id,decision:'rejected'},'تم رفض الطلب');break;case 'preparePayroll':prepareMonthForm();break;case 'approvePayroll':await mutate('payroll.approve',{id},'تم اعتماد الكشف من المالية');break;case 'sendPayroll':modal('<h2>'+(LIVE?'إرسال كشوف الرواتب':'محاكاة إرسال الكشوف')+'</h2><p>'+(LIVE?'سيتم إنشاء PDF خاص وإرساله إلى بريد كل موظف مسجل في هذا الكشف المعتمد.':'ستُحدَّث حالات التسليم في العرض فقط؛ لن تخرج أي رسائل.')+'</p><div class="form-actions">'+btn('تأكيد '+(LIVE?'الإرسال':'المحاكاة'),'confirmSend',id,'primary')+'</div>');break;case 'confirmSend':if(LIVE){if(busy)return;busy=true;try{const result=await callServer('sendPayroll',{id});state=await callServer('getState');closeModal();render();toast(result.message);}finally{busy=false;}}else await mutate('payroll.simulate',{id},'اكتملت المحاكاة. لم تُرسل رسائل حقيقية.');break;case 'payslip':payslip(id);break;case 'print':window.print();break;case 'offboardingForm':form('بدء إنهاء خدمة',selectField('الموظف','employeeId',employeeOptions(true))+selectField('السبب','reason',['استقالة','انتهاء عقد','إنهاء خدمة بقرار الإدارة'])+field('آخر يوم عمل','lastDay','date',new Date().toISOString().slice(0,10)),'offboarding');break;case 'exitTask':await mutate('offboarding.task',{id,index:Number(el.dataset.index),done:el.checked},'تم تحديث إخلاء الطرف');break;case 'finalizeExit':modal('<h2>إغلاق ملف إنهاء الخدمة</h2><p>يُغيّر هذا الموظف إلى غير نشط، بعد اكتمال كل المهام وبلوغ آخر يوم عمل. القرار الإداري مسؤولية الإنسان.</p><div class="form-actions">'+btn('تأكيد الإغلاق','confirmExit',id,'danger')+'</div>');break;case 'confirmExit':await mutate('offboarding.finalize',{id},'تم إغلاق الحالة وأرشفة الموظف');break;case 'reviewForm':form('مراجعة أداء',selectField('الموظف','employeeId',employeeOptions(true))+field('التقييم (1–5)','score','number','4','min="1" max="5" step="0.5"')+'<div class="field"><label>ملاحظات وخطة تطوير</label><textarea name="notes" required></textarea></div>','review');break;case 'eventForm':form('موعد على التقويم',field('العنوان','title')+field('التاريخ','date','date',new Date().toISOString().slice(0,10))+selectField('النوع','type',[{value:'general',label:'عام'},{value:'review',label:'مراجعة أداء'},{value:'onboarding',label:'تهيئة موظف'},{value:'payroll',label:'رواتب'}]),'event');break;case 'exportEmployees':download('employees.csv',csv([['ID','Name','Email','Department','Job','Status','Joined'],...scopedEmployees().map(e=>[e.id,e.name,e.email,e.department,e.job,e.status,e.joinDate])]),'text/csv');break;case 'exportPayroll':{const r=state.payroll.find(r=>r.id===id);download('payroll-'+r.month+'.csv',csv([['ID','Name','Email','Basic','Allowance','Bonus','Deduction','Net'],...r.rows.map(e=>[e.employeeId,e.name,e.email,e.basic,e.allowance,e.bonus,e.deduction,e.net])]),'text/csv');break;}case 'exportData':download('zarqa-people-data.json',JSON.stringify(state,null,2),'application/json');break;case 'importData':modal('<h2>استيراد نسخة احتياطية</h2><p>تستبدل بيانات العرض في هذا المتصفح فقط. الاستيراد لا ينفذ أي إرسال.</p><input type="file" id="dataImport" accept="application/json"><div class="form-actions">'+btn('استيراد واستبدال','confirmImport','','primary')+'</div>');break;case 'confirmImport':{const file=$('dataImport').files[0];if(!file||file.size>5000000)throw Error('اختر JSON أقل من 5 MB');const s=JSON.parse(await file.text());if(s.schema!==1||!s.settings||!['employees','attendance','jobs','candidates','leaves','policies','payroll','offboarding','reviews','events','audit'].every(k=>Array.isArray(s[k])))throw Error('بنية الملف غير صالحة');if(!/^#[0-9a-f]{6}$/i.test(s.settings.accent))throw Error('الإعدادات غير صحيحة');s.settings.autoSend=false;state=s;closeModal();render();toast('تم استيراد نسخة العرض؛ الجدولة متوقفة');break;}case 'resetDemo':modal('<h2>بدء عرض جديد</h2><p>سيتم استبدال تغييرات العرض ببياناته الأصلية. صدّر JSON للاحتفاظ بتعديلاتك.</p><div class="form-actions">'+btn('استعادة البيانات التجريبية','confirmReset','','danger')+'</div>');break;case 'confirmReset':state=makeSeed();closeModal();render();toast('تمت استعادة بيانات العرض');break;case 'integration':integration();break;case 'demoCredentials':document.getElementById('login-user').value='employee1@example.com';document.getElementById('login-pass').value='welcome123';break;case 'logoutDemo':employeeSession=false;role='admin';employeeId='EMP-048';navigate('dashboard');break;case 'myPayslip':month=id;payslip(employeeId);break;} }catch(err){toast(err.message||String(err));}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('form'))return;e.preventDefault();if(form.id==='documentUpload'||form.id==='readingPreferencesForm'||form.dataset.ops)return;const fd=new FormData(form),p=Object.fromEntries(fd.entries());if(form.id==='portalLogin'){if(LIVE)return toast('Use your Google Workspace identity.');const e=state.employees.find(e=>e.email.toLowerCase()===String(p.username).toLowerCase());if(!e||p.password!=='welcome123')return toast('راجع بيانات الدخول التجريبية');if(e.status==='inactive')return toast('حساب الموظف غير نشط');role='employee';employeeId=e.id;employeeSession=true;actorEmail=e.email;navigate('selfservice');return;}if(form.id==='settingsForm'){const file=$('logoUpload').files[0];p.logo=state.settings.logo;p.autoSend=fd.get('autoSend')==='on';if(file){if(file.size>500000)return toast('اختر شعارًا أقل من 500 KB');p.logo=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(file);});}await mutate('settings.save',p,'تم تحديث هوية الشركة');return;}const type=form.dataset.form;if(type==='requirements')p.items=String(p.requirements).split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(type==='candidateMove')p.stage=Number(p.stage);if(type==='module'){p.answer=Number(p.answer);p.ack=fd.get('ack')==='on';}if(type==='policy'){p.options=[p.option0,p.option1,p.option2];p.correct=Number(p.correct);}const map={employee:'employee.add',job:'job.add',candidate:'candidate.add',candidateMove:'candidate.move',leave:'leave.create',module:'onboarding.complete',offboarding:'offboarding.add',review:'review.add',event:'event.add',policy:'policy.save',employeeEdit:'employee.edit',access:'access.set',payrollRow:'payroll.updateRow',documentReview:'document.review',requirements:'documents.requirements'};await mutate(map[type],p,type==='module'?'اجتزت المحطة وسُجّل الإقرار ✓':'تم الحفظ');});
document.addEventListener('change',e=>{switch(e.target.id){case 'dateFrom':if(!e.target.value)return;from=e.target.value;break;case 'dateTo':if(!e.target.value)return;to=e.target.value;break;case 'department':department=e.target.value;break;case 'payMonth':if(!e.target.value)return;month=e.target.value;break;case 'onboardingEmployee':employeeFocus=e.target.value;if(role==='employee'&&!LIVE)employeeId=e.target.value;break;case 'roleSelect':if(LIVE)return;role=e.target.value;employeeId=({manager:'EMP-005',hr:'EMP-004',finance:'EMP-010',admin:'EMP-048',employee:'EMP-001'})[role];break;default:return;}if(from>to){toast('تاريخ البداية يجب أن يسبق النهاية');from='2026-10-01';to='2026-10-31';}render();});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const pos=e.target.selectionStart;render();$('search').focus();$('search').setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('.candidate'))e.target.click();});
$('closeDialog').onclick=closeModal;$('helpButton').onclick=help;$('menuButton').onclick=()=>setSidebar(!$('sidebar').classList.contains('open'));$('sidebarClose').onclick=()=>setSidebar(false);$('navBackdrop').onclick=()=>setSidebar(false);window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next&&next!==page){page=next;render();}});
page=location.hash.slice(1)||'dashboard';render();
if(LIVE){$('main').innerHTML='<div class="empty">جارٍ تحميل مساحة العمل المصرح بها…</div>';callServer('bootstrap').then(r=>{state=hrEnsureOperations(r.state);role=r.actor.role;employeeSession=role==='employee';if(employeeSession)page='selfservice';employeeId=r.actor.employeeId;actorEmail=r.actor.email;employeeFocus=employeeId||state.employees[0]?.id;$('roleSelect').disabled=true;$('modeBadge').textContent='GOOGLE WORKSPACE • متصل';$('modeBadge').className='badge green';$('storageLabel').textContent='متصل بـ Google Workspace';$('storageDetail').textContent='Sheets + Drive · صلاحيات الخادم';$('footerText').textContent='مساحة عمل متصلة · سجل إجراءات محفوظ';render();}).catch(e=>{$('main').innerHTML='<div class="notice">تعذر تحميل المساحة: '+esc(e.message||e)+'</div>';});}
